// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Bound values to avoid overflow and ensure reasonable test space
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 0, 1e18);

        // Initialize contract: set MinSum to 0 and log file
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record contract balance before Collect
        uint256 balanceBefore = address(c).balance;

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record contract balance after Collect
        uint256 balanceAfter = address(c).balance;

        // The rule: the contract balance should never increase after a Collect call
        // In the reference, the balance either stays same (if collect fails) or decreases (if collect succeeds)
        // In the buggy version, if Deposit reverts, the contract may have less ether from the start, but Collect still cannot increase it
        assertTrue(balanceAfter <= balanceBefore);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

